def find_initial_cards(n, d, l):
    # Try to find a valid initial set of cards
    for a in range(1, l + 1):
        for b in range(1, l + 1):
            cards = [a, b]
            for _ in range(n - 2):
                next_card = cards[-1] - cards[-2]
                cards.append(next_card)
            if cards[-1] == d and len(cards) == n:
                return ' '.join(map(str, cards))
    return -1

